measure.py.contents:
#!/usr/bin/env python3
import hashlib,json,os,re,statistics,subprocess
from pathlib import Path
W=Path(__file__).resolve().parent
variants={'small-before':'0-Main/baseline.test','small-after':'treatment-small/treatment.test','heavy-before':'1-Heavy/baseline.test','heavy-after':'treatment-heavy/treatment.test'}
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
hashes={n:sha(W/p) for n,p in variants.items()}
orders=[list(variants),list(reversed(variants)),list(variants)[2:]+list(variants)[:2]]
results={n:[] for n in variants}
env={**os.environ,'GOMAXPROCS':'1','GOGC':'100'}
for round,order in enumerate(orders):
 for name in order:
  output=subprocess.check_output([str(W/variants[name]),'-test.run','^$','-test.bench','^BenchmarkGeneratedPipeline$','-test.benchtime=200ms','-test.count=1','-test.benchmem'],env=env,text=True)
  (W/f'bench-{round}-{name}.txt').write_text(output)
  cells={k:{'ns':float(ns),'bytes':int(b),'allocs':int(a)} for k,ns,b,a in re.findall(r'BenchmarkGeneratedPipeline/(\w+)\s+\d+\s+([\d.]+) ns/op\s+(\d+) B/op\s+(\d+) allocs/op',output)}
  assert len(cells)==3 and output.strip().endswith('PASS'),output
  results[name].append(cells)
  print(round,name,json.dumps(cells),flush=True)
assert hashes=={n:sha(W/p) for n,p in variants.items()}
medians={n:{k:{metric:statistics.median(run[k][metric] for run in runs) for metric in ['ns','bytes','allocs']} for k in ['A','B','C']} for n,runs in results.items()}
sizes={n:(W/p).stat().st_size for n,p in {'small-before':'0-Main/baseline','small-after':'treatment-small/treatment','heavy-before':'1-Heavy/baseline','heavy-after':'treatment-heavy/treatment'}.items()}
r={'protocol':{'rounds':3,'benchtime':'200ms','GOMAXPROCS':1,'GOGC':100,'PGO':False,'orders':orders,'aggregation':'median of three Go ns/op samples from separate processes','competing_task_builds_tests':False},'samples':results,'medians':medians,'binary_sha256':hashes,'application_bytes':sizes,'versions':{'go':subprocess.check_output(['go','version'],text=True).strip()},'readme_baselines_ms':{'JSON Decoding':{'go':45.82,'js':8.65},'JSON to Typed AST':{'go':567.61,'js':79.06}},'scope':'PureScript-generated record construction + shared read, not a JSON timing'}
(W/'results.json').write_text(json.dumps(r,indent=2)+'\n')
print(json.dumps({'medians':medians,'application_bytes':sizes},indent=2),flush=True)

