package purescript

import "testing"

var generatedScoreSink int64

func oracleScore(id int64, name string, active bool) int64 {
	a := id * 3
	if active {
		a += 7
	}
	var b, c, d, e, f, g int64
	if active {
		b = a*7 + 17
	} else {
		b = a*5 - 13
	}
	if name == "alpha" {
		c = b + id*11
	} else {
		c = b - id*13
	}
	if c < 100 {
		d = c*2 + 7
	} else {
		d = c*2 - 7
	}
	if active {
		e = d + a*3
	} else {
		e = d - b
	}
	if name == "beta" {
		f = e + 19
	} else {
		f = e - 23
	}
	if id < 0 {
		g = f - 29
	} else {
		g = f + 31
	}
	h := g + a + b + c + d + e + f
	if h > 200 {
		return h + b*3 - a*2
	}
	return h - b*3 + a*2
}
func TestGeneratedPipelines(t *testing.T) {
	for n := int64(-128); n < 128; n++ {
		for _, c := range []struct {
			name   string
			run    func(int64) int64
			text   string
			active bool
		}{{"A", Call_Main_runA, "alpha", true}, {"B", Call_Main_runB, "beta", false}, {"C", Call_Main_runC, "alpha", true}} {
			if got, want := c.run(n), oracleScore(n, c.text, c.active); got != want {
				t.Fatalf("%s %d got %d want %d", c.name, n, got, want)
			}
		}
	}
}
func BenchmarkGeneratedPipeline(b *testing.B) {
	for _, c := range []struct {
		name string
		run  func(int64) int64
	}{{"A", Call_Main_runA}, {"B", Call_Main_runB}, {"C", Call_Main_runC}} {
		b.Run(c.name, func(b *testing.B) {
			b.ReportAllocs()
			var sum int64
			for i := 0; i < b.N; i++ {
				sum += c.run(int64(i&255) - 128)
			}
			generatedScoreSink = sum
		})
	}
}

func TestDynamicFields(t *testing.T) {
 for n:=int64(-128);n<128;n++ { for _,text:=range []string{"alpha","beta"} { for _,flag:=range []bool{false,true} {
   if got,want:=Call_Main_runFields(n,text,flag),oracleScore(n,text,flag);got!=want { t.Fatalf("%d %q %t: got %d want %d",n,text,flag,got,want) }
 } } }
}
func BenchmarkDynamicFields(b *testing.B) {
 names:=[2]string{"alpha","beta"};b.ReportAllocs();var sum int64
 for i:=0;i<b.N;i++ { sum+=Call_Main_runFields(int64(i&255)-128,names[(i>>3)&1],(i&16)==0) }
 generatedScoreSink=sum
}

